"""Golden tests that pin the exact wording and wire behaviour of --fix, --profile and the audit
bookkeeping around them (written from mutation survivors: every line of fix_snippet's output,
the CLI help of the new options, the stdout/stderr bytes of `--fix -`, and parse/audit edge cases)."""
import contextlib
import io
import json
import os
import re
import sys
import tempfile
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))
import sshd_audit as sa  # noqa: E402

HEADER = (
    "# Generated by sshd-hardening-auditor --fix. Review before use.\n"
    "# sshd keeps the FIRST value it sees: install this file where its Include line comes before\n"
    "# the conflicting directives (Debian/Ubuntu/Fedora put `Include /etc/ssh/sshd_config.d/*.conf`\n"
    "# at the top of sshd_config). Check with `sshd -t`, keep a second session open, then reload.\n"
    "\n"
)
LOCKOUT = "# Make sure a working key login exists first, or this locks you out.\n"
ALLOW = "# AllowUsers/AllowGroups: needs your list of accounts, e.g. `AllowGroups ssh-users`\n"
NOTHING = "# Nothing to fix.\n"


def weak(key):
    return "# %s: remove the weak algorithm(s) reported above (e.g. `%s -<name>`)\n" % (key, key)


def res(key, ok=False):
    return {"key": key, "pass": ok}


def run(argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        rc = sa.main(argv)
    return rc, out.getvalue(), err.getvalue()


def squash(s):
    return " ".join(s.split())


class TestFixSnippetGolden(unittest.TestCase):
    def test_mixed_results_exact_text(self):
        got = sa.fix_snippet([
            res("PasswordAuthentication"), res("MaxAuthTries"), res("AllowUsers/AllowGroups"),
            res("KexAlgorithms"), res("Ciphers:3des"), res("MACs"), res("HostKeyAlgorithms"),
            res("UsePAM", True), res("Protocol")])
        want = (HEADER + LOCKOUT + "PasswordAuthentication no\nMaxAuthTries 4\n" + ALLOW
                + weak("KexAlgorithms") + weak("Ciphers:3des") + weak("MACs") + weak("HostKeyAlgorithms"))
        self.assertEqual(got, want)

    def test_every_directive_counts_once(self):
        # each fixed directive is one line; the lock-out warning only precedes PasswordAuthentication
        got = sa.fix_snippet([res("PermitRootLogin"), res("LogLevel"), res("MaxSessions")])
        self.assertEqual(got, HEADER + "PermitRootLogin no\nLogLevel VERBOSE\nMaxSessions 10\n")
        self.assertNotIn("locks you out", got)

    def test_nothing_to_fix_only_when_no_fix_and_no_todo(self):
        self.assertEqual(sa.fix_snippet([res("UsePAM", True)]), HEADER + NOTHING)
        self.assertEqual(sa.fix_snippet([]), HEADER + NOTHING)
        self.assertEqual(sa.fix_snippet([res("Weird")]), HEADER + NOTHING)
        # a to-do line alone (nothing fixable) is not "nothing to fix"
        self.assertEqual(sa.fix_snippet([res("AllowUsers/AllowGroups")]), HEADER + ALLOW)
        # a fixable directive alone is not "nothing to fix" either
        self.assertEqual(sa.fix_snippet([res("UsePAM")]), HEADER + "UsePAM yes\n")

    def test_algorithm_keys_are_matched_case_insensitively_by_directive(self):
        got = sa.fix_snippet([res("kexalgorithms"), res("CIPHERS"), res("Macs: x"), res("hostkeyalgorithms")])
        self.assertEqual(got, HEADER + weak("kexalgorithms") + weak("CIPHERS") + weak("Macs: x")
                         + weak("hostkeyalgorithms"))

    def test_each_algorithm_directive_alone(self):
        for key in ("KexAlgorithms", "Ciphers", "MACs", "HostKeyAlgorithms"):
            self.assertEqual(sa.fix_snippet([res(key)]), HEADER + weak(key), key)

    def test_algorithm_key_must_start_with_the_directive(self):
        # only the part before ':' names the directive
        self.assertEqual(sa.fix_snippet([res("Other:Ciphers")]), HEADER + NOTHING)
        self.assertEqual(sa.fix_snippet([res("x Ciphers")]), HEADER + NOTHING)

    def test_passing_results_are_skipped(self):
        self.assertEqual(sa.fix_snippet([res("PermitRootLogin", True), res("Ciphers", True),
                                         res("AllowUsers/AllowGroups", True)]), HEADER + NOTHING)


class TestFixCli(unittest.TestCase):
    BAD = "PermitRootLogin yes\nMaxAuthTries 10\n"

    def _cfg(self, d, text=None):
        p = os.path.join(d, "sshd_config")
        with open(p, "w") as f:
            f.write(self.BAD if text is None else text)
        return p

    def _expected(self, d):
        p = self._cfg(d)
        results = sa.audit(sa.parse_sshd_config(self.BAD))
        return p, sa.fix_snippet(results)

    def test_stdout_is_newline_then_snippet_exactly(self):
        with tempfile.TemporaryDirectory() as d:
            p, snip = self._expected(d)
            rc, out, err = run(["--no-file-checks", "--fix", "-", p])
        self.assertEqual(err, "")
        self.assertTrue(out.endswith("\n" + snip), out[-300:])
        # nothing but the snippet's own final newline after it, and one blank line before it
        self.assertEqual(out.count(snip), 1)
        self.assertTrue(snip.endswith("\n") and not snip.endswith("\n\n"))
        head = out[:len(out) - len(snip)]
        self.assertTrue(head.endswith("\n\n") or head.endswith("\n"))
        self.assertFalse(out.endswith("\n\n"))

    def test_json_mode_sends_the_snippet_to_stderr_verbatim(self):
        with tempfile.TemporaryDirectory() as d:
            p, snip = self._expected(d)
            rc, out, err = run(["--no-file-checks", "--json", "--fix", "-", p])
        self.assertEqual(err, snip)
        json.loads(out)

    def test_file_content_is_the_snippet_exactly(self):
        with tempfile.TemporaryDirectory() as d:
            p, snip = self._expected(d)
            f = os.path.join(d, "fix.conf")
            run(["--no-file-checks", "--fix", f, p])
            with open(f) as fh:
                self.assertEqual(fh.read(), snip)

    def test_error_message_names_the_tool(self):
        with tempfile.TemporaryDirectory() as d:
            p = self._cfg(d)
            rc, out, err = run(["--no-file-checks", "--fix", os.path.join(d, "no", "f"), p])
        self.assertEqual(rc, 2)
        self.assertTrue(err.startswith("sshd-hardening-auditor: ERROR -- "), err)

    def test_default_profile_is_l2(self):
        with tempfile.TemporaryDirectory() as d:
            p = self._cfg(d, "X11Forwarding yes\n")
            _, out, _ = run(["--no-file-checks", "--fail-on", "never", p])
        self.assertIn("X11Forwarding = yes", out)

    def test_profile_and_fix_help_text(self):
        old = os.environ.get("COLUMNS")
        os.environ["COLUMNS"] = "200"
        out = io.StringIO()
        try:
            with contextlib.redirect_stdout(out):
                try:
                    sa.main(["--help"])
                except SystemExit:
                    pass
        finally:
            if old is None:
                os.environ.pop("COLUMNS", None)
            else:
                os.environ["COLUMNS"] = old
        h = squash(out.getvalue())
        self.assertIn("--profile {l1,l2}", h)
        self.assertIn("--fix FILE", h)
        self.assertIn("CIS profile: l1 = Level 1 rules only (X11Forwarding, AllowTcpForwarding and "
                      "GSSAPIAuthentication are Level 2), l2 = all rules (default)", h)
        self.assertIn("write an sshd_config drop-in that sets every failing directive to the recommended "
                      "value ('-' = stdout, stderr with --json); the config itself is never edited", h)


class TestParseAndAuditEdges(unittest.TestCase):
    def test_only_first_hash_starts_a_comment(self):
        cfg = sa.parse_sshd_config("Banner /etc/a # one # two\n")
        self.assertEqual(cfg["banner"], "/etc/a")

    def test_inline_comment_is_stripped(self):
        cfg = sa.parse_sshd_config("PermitRootLogin no # fine\n# whole line\n")
        self.assertEqual(cfg["permitrootlogin"], "no")
        self.assertEqual(cfg["_all"], [("permitrootlogin", "no")])

    def test_valueless_keyword_is_skipped_not_fatal(self):
        cfg = sa.parse_sshd_config("Banner\nPermitRootLogin no\nUsePAM =\nMaxAuthTries 3\n")
        self.assertEqual(cfg["permitrootlogin"], "no")
        self.assertEqual(cfg["maxauthtries"], "3")
        self.assertNotIn("banner", cfg)
        self.assertNotIn("usepam", cfg)

    def test_match_keyword_alone_ends_global_section(self):
        cfg = sa.parse_sshd_config("Match\nPermitRootLogin yes\n")
        self.assertNotIn("permitrootlogin", cfg)

    def test_allow_deny_lists_are_joined_in_order(self):
        cfg = sa.parse_sshd_config("AllowUsers a\nAllowGroups g\nDenyUsers u\nDenyGroups d\n")
        r = [x for x in sa.audit(cfg) if x["key"] == "AllowUsers/AllowGroups"][0]
        self.assertEqual(r["value"], "allowusers a; allowgroups g; denyusers u; denygroups d")
        self.assertTrue(r["pass"])

    def test_each_allow_deny_directive_counts_alone(self):
        for k in ("allowusers", "allowgroups", "denyusers", "denygroups"):
            r = [x for x in sa.audit({k: "x"}) if x["key"] == "AllowUsers/AllowGroups"][0]
            self.assertEqual(r["value"], k + " x")

    def test_no_allow_deny_shows_none(self):
        r = [x for x in sa.audit({}) if x["key"] == "AllowUsers/AllowGroups"][0]
        self.assertEqual(r["value"], "(none)")
        self.assertFalse(r["pass"])

    def test_deprecated_alias_value_is_used(self):
        r = [x for x in sa.audit({"challengeresponseauthentication": "yes"})
             if x["key"] == "KbdInteractiveAuthentication"][0]
        self.assertEqual(r["value"], "yes")
        self.assertFalse(r["pass"])
        r = [x for x in sa.audit({"challengeresponseauthentication": "no"})
             if x["key"] == "KbdInteractiveAuthentication"][0]
        self.assertEqual(r["value"], "no")
        self.assertTrue(r["pass"])

    def test_default_value_is_labelled(self):
        r = [x for x in sa.audit({}) if x["key"] == "MaxAuthTries"][0]
        self.assertEqual(r["value"], "6 (default)")
        r = [x for x in sa.audit({}) if x["key"] == "Banner"][0]
        self.assertEqual(r["value"], "none (default)")

    def test_rule_without_custom_check_compares_to_expected(self):
        plain = [r for r in sa.RULES if r.check is None and r.key != "AllowUsers/AllowGroups"]
        for rule in plain:
            ok = [x for x in sa.audit({rule.key.lower(): rule.expected}) if x["key"] == rule.key][0]
            bad = [x for x in sa.audit({rule.key.lower(): rule.expected + "-other"}) if x["key"] == rule.key][0]
            self.assertTrue(ok["pass"], rule.key)
            self.assertFalse(bad["pass"], rule.key)

    def test_audit_default_profile_is_l2(self):
        self.assertEqual(len(sa.audit({})), len(sa.RULES))
        self.assertEqual(len(sa.audit({}, "l1")), len([r for r in sa.RULES if r.level == 1]))


if __name__ == "__main__":
    unittest.main()
